import java.util.*;

public class Main {
    public static void main(String[] args) {
        int n = 5;
        int[][] edges = {{0, 1}, {0, 2}, {1, 3}, {2, 3}, {3, 4}};
        List<List<Integer>> adj = new ArrayList<>();      // list: one neighbour list per node
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        int[][] mat = new int[n][n];                      // matrix: n x n table of 0/1
        for (int[] e : edges) {
            adj.get(e[0]).add(e[1]); adj.get(e[1]).add(e[0]);   // undirected: both directions
            mat[e[0]][e[1]] = 1; mat[e[1]][e[0]] = 1;
        }
        System.out.println("nodes: " + n + " edges: " + edges.length);
        for (int u = 0; u < n; u++) {
            StringBuilder sb = new StringBuilder("list " + u + " ->");
            for (int v : adj.get(u)) sb.append(" ").append(v);
            System.out.println(sb);
        }
        for (int u = 0; u < n; u++) {
            StringBuilder sb = new StringBuilder("matrix " + u + " :");
            for (int x : mat[u]) sb.append(" ").append(x);
            System.out.println(sb);
        }
        // Edge check: the matrix is one lookup O(1); the list scans neighbours O(degree)
        System.out.println("edge 1-3? matrix: " + (mat[1][3] == 1 ? "yes" : "no") + " list: " + (adj.get(1).contains(3) ? "yes" : "no"));
        System.out.println("edge 0-4? matrix: " + (mat[0][4] == 1 ? "yes" : "no") + " list: " + (adj.get(0).contains(4) ? "yes" : "no"));
        // Space: list O(V + E), matrix O(V^2)
        System.out.println("list entries = " + 2 * edges.length + " (2E), matrix cells = " + n * n + " (V*V)");
    }
}

