    vector<vector<int>> mat(n, vector<int>(n, 0)); // matrix: n x n table of 0/1
    for (auto [u, v] : edges) {
        adj[u].push_back(v); adj[v].push_back(u);  // undirected: store both directions
        mat[u][v] = 1; mat[v][u] = 1;
    }
    cout << "nodes: " << n << " edges: " << edges.size() << "\n";
    for (int u = 0; u < n; u++) {
        cout << "list " << u << " ->";
        for (int v : adj[u]) cout << " " << v;
        cout << "\n";
    }
    for (int u = 0; u < n; u++) {
        cout << "matrix " << u << " :";
        for (int x : mat[u]) cout << " " << x;
        cout << "\n";
    }
    // Edge check: the matrix is one lookup O(1); the list scans neighbours O(degree)
    auto inList = [&](int u, int v) { return find(adj[u].begin(), adj[u].end(), v) != adj[u].end(); };
    cout << "edge 1-3? matrix: " << (mat[1][3] == 1 ? "yes" : "no") << " list: " << (inList(1, 3) ? "yes" : "no") << "\n";
