code.java:
import java.util.*;

public class Main {
    public static void main(String[] args) {
        int n = 7;
        int[][] edges = {{0, 1}, {0, 2}, {1, 3}, {2, 3}, {3, 4}, {4, 5}};
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) { adj.get(e[0]).add(e[1]); adj.get(e[1]).add(e[0]); }

        int src = 0, target = 5;
        int[] dist = new int[n], parent = new int[n];
        Arrays.fill(dist, -1);                 // -1 means "not discovered yet"
        Arrays.fill(parent, -1);
        dist[src] = 0;
        ArrayDeque<Integer> q = new ArrayDeque<>();
        q.add(src);
        while (!q.isEmpty()) {
            int u = q.poll();                  // FIFO: nodes leave in order of distance
            for (int v : adj.get(u)) {
                if (dist[v] == -1) {           // the first discovery is the shortest distance
                    dist[v] = dist[u] + 1;
                    parent[v] = u;
                    q.add(v);
                }
            }
        }
        List<Integer> path = new ArrayList<>();
        for (int x = target; x != -1; x = parent[x]) path.add(x);  // walk parents back to the source
        Collections.reverse(path);
        StringBuilder a = new StringBuilder("dist from 0:"), b = new StringBuilder("path 0 -> 5:");
        for (int d : dist) a.append(" ").append(d);
        for (int p : path) b.append(" ").append(p);
        System.out.println("edges: 0-1 0-2 1-3 2-3 3-4 4-5, node 6 is isolated");
        System.out.println(a);
        System.out.println(b);
        // Time O(V + E), space O(V)
    }
}

