class Program {
    static void Main() {
        int n = 7;
        int[][] edges = { new[] {0, 1}, new[] {0, 2}, new[] {1, 3}, new[] {2, 3}, new[] {3, 4}, new[] {4, 5} };
        List<int>[] adj = new List<int>[n];
        for (int i = 0; i < n; i++) adj[i] = new List<int>();
        foreach (int[] e in edges) { adj[e[0]].Add(e[1]); adj[e[1]].Add(e[0]); }

        int src = 0, target = 5;
        int[] dist = new int[n], parent = new int[n];
        for (int i = 0; i < n; i++) { dist[i] = -1; parent[i] = -1; }  // -1 means "not discovered yet"
        dist[src] = 0;
        Queue<int> q = new Queue<int>();
        q.Enqueue(src);
        while (q.Count > 0) {
            int u = q.Dequeue();               // FIFO: nodes leave in order of distance
            foreach (int v in adj[u]) {
                if (dist[v] == -1) {           // the first discovery is the shortest distance
                    dist[v] = dist[u] + 1;
                    parent[v] = u;
                    q.Enqueue(v);
                }
            }
        }
        List<int> path = new List<int>();
        for (int x = target; x != -1; x = parent[x]) path.Add(x);  // walk parents back to the source
        path.Reverse();
        string a = "dist from 0:", b = "path 0 -> 5:";
        foreach (int d in dist) a += " " + d;
        foreach (int p in path) b += " " + p;
        Console.WriteLine("edges: 0-1 0-2 1-3 2-3 3-4 4-5, node 6 is isolated");
        Console.WriteLine(a);
        Console.WriteLine(b);
        // Time O(V + E), space O(V)
    }
}

