code.js:
function dfs(u, par, adj, seen) {
  seen[u] = true;
  for (const v of adj[u]) {
    if (v === par) continue;               // the edge we came in on is not a cycle
    if (seen[v] || dfs(v, u, adj, seen)) return true;  // visited and not the parent: cycle
  }
  return false;
}
function find(parent, x) {
  while (parent[x] !== x) {
    parent[x] = parent[parent[x]];         // path halving keeps the trees short
    x = parent[x];
  }
  return x;
}
function check(name, n, edges) {
  let line = name + " edges:";
  for (const [u, v] of edges) line += " " + u + "-" + v;
  console.log(line);
  const adj = Array.from({ length: n }, () => []);
  for (const [u, v] of edges) { adj[u].push(v); adj[v].push(u); }
  const seen = new Array(n).fill(false);
  let cyc = false;
  for (let s = 0; s < n; s++)              // start from every unvisited node
    if (!seen[s] && dfs(s, -1, adj, seen)) cyc = true;
  console.log("  DFS with parent: " + (cyc ? "cycle" : "no cycle"));
  const parent = [];
  for (let i = 0; i < n; i++) parent.push(i);
  let closing = "";
  for (const [u, v] of edges) {
    const ru = find(parent, u), rv = find(parent, v);
    if (ru === rv) { closing = u + "-" + v; break; }  // same group already: this edge closes a cycle
    parent[ru] = rv;
  }
  console.log("  DSU: " + (closing ? "cycle, closed by edge " + closing : "no cycle"));
}
check("tree", 4, [[0, 1], [1, 2], [1, 3]]);
check("graph", 4, [[0, 1], [1, 2], [2, 3], [3, 1]]);
// DFS: O(V + E) time. DSU: almost O(1) per edge. Both use O(V) space.

