import java.util.*;

public class Main {
    static boolean dfs(int u, int par, List<List<Integer>> adj, boolean[] seen) {
        seen[u] = true;
        for (int v : adj.get(u)) {
            if (v == par) continue;                 // the edge we came in on is not a cycle
            if (seen[v] || dfs(v, u, adj, seen)) return true;  // visited and not the parent: cycle
        }
        return false;
    }
    static int find(int[] parent, int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];          // path halving keeps the trees short
            x = parent[x];
        }
        return x;
    }
    static void check(String name, int n, int[][] edges) {
        StringBuilder line = new StringBuilder(name + " edges:");
        for (int[] e : edges) line.append(" ").append(e[0]).append("-").append(e[1]);
        System.out.println(line);
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) { adj.get(e[0]).add(e[1]); adj.get(e[1]).add(e[0]); }
        boolean[] seen = new boolean[n];
        boolean cyc = false;
        for (int s = 0; s < n; s++)                 // start from every unvisited node
            if (!seen[s] && dfs(s, -1, adj, seen)) cyc = true;
        System.out.println("  DFS with parent: " + (cyc ? "cycle" : "no cycle"));
        int[] parent = new int[n];
        for (int i = 0; i < n; i++) parent[i] = i;
        String closing = "";
        for (int[] e : edges) {
            int ru = find(parent, e[0]), rv = find(parent, e[1]);
            if (ru == rv) { closing = e[0] + "-" + e[1]; break; }  // same group already: cycle
            parent[ru] = rv;
        }
        System.out.println("  DSU: " + (closing.isEmpty() ? "no cycle" : "cycle, closed by edge " + closing));
    }
