function recursive(u, adj, seen, post) {
  seen[u] = true;
  for (const v of adj[u]) if (!seen[v]) recursive(v, adj, seen, post);
  post.push(u);
}
function iterative(start, adj) {
  const n = adj.length;
  const seen = new Array(n).fill(false), nxt = new Array(n).fill(0), post = [];  // nxt[u] = next neighbour to try
  const stack = [start];
  seen[start] = true;
  while (stack.length > 0) {
    const u = stack[stack.length - 1];   // look at the top frame, do not pop it yet
    if (nxt[u] < adj[u].length) {
      const v = adj[u][nxt[u]];
      nxt[u]++;                          // remember where to resume, like a paused call
      if (!seen[v]) { seen[v] = true; stack.push(v); }
    } else {
      stack.pop();                       // all neighbours done: u finishes ("return")
      post.push(u);
    }
  }
  return post;
}
