import java.util.*;

public class Main {
    static void recursive(int u, int[][] adj, boolean[] seen, List<Integer> post) {
        seen[u] = true;
        for (int v : adj[u]) if (!seen[v]) recursive(v, adj, seen, post);
        post.add(u);
    }
    static List<Integer> iterative(int start, int[][] adj) {
        int n = adj.length;
        boolean[] seen = new boolean[n];
        int[] nxt = new int[n];                    // nxt[u] = which neighbour of u to try next
        List<Integer> post = new ArrayList<>();
        ArrayDeque<Integer> stack = new ArrayDeque<>();
        stack.push(start);
        seen[start] = true;
        while (!stack.isEmpty()) {
            int u = stack.peek();                  // look at the top frame, do not pop it yet
            if (nxt[u] < adj[u].length) {
                int v = adj[u][nxt[u]++];          // remember where to resume, like a paused call
                if (!seen[v]) { seen[v] = true; stack.push(v); }
            } else {
                stack.pop();                       // all neighbours done: u finishes ("return")
                post.add(u);
            }
        }
        return post;
    }
    public static void main(String[] args) {
        int[][] adj = {{1, 2}, {3, 4}, {4}, {}, {5}, {}};
        List<Integer> rec = new ArrayList<>();
        recursive(0, adj, new boolean[6], rec);
        StringBuilder a = new StringBuilder("recursive post-order:"), b = new StringBuilder("iterative post-order:");
        for (int x : rec) a.append(" ").append(x);
        for (int x : iterative(0, adj)) b.append(" ").append(x);
        System.out.println("edges: 0->1 0->2 1->3 1->4 2->4 4->5");
        System.out.println(a);
        System.out.println(b);
        int N = 200000;                            // a chain this deep would overflow a recursive DFS
        int[][] chain = new int[N][];
        for (int i = 0; i < N; i++) chain[i] = i + 1 < N ? new int[]{i + 1} : new int[0];
        List<Integer> p = iterative(0, chain);
        System.out.println("chain of " + N + " nodes: visited " + p.size() + ", first finished " + p.get(0) + ", last finished " + p.get(p.size() - 1));
        // Time O(V + E), space O(V) on the heap instead of the call stack
    }
}

