using namespace std;

void recursive(int u, vector<vector<int>>& adj, vector<bool>& seen, vector<int>& post) {
    seen[u] = true;
    for (int v : adj[u]) if (!seen[v]) recursive(v, adj, seen, post);
    post.push_back(u);
}
vector<int> iterative(int start, vector<vector<int>>& adj) {
    int n = adj.size();
    vector<bool> seen(n, false);
    vector<int> nxt(n, 0), post, stack;            // nxt[u] = which neighbour of u to try next
    stack.push_back(start);
    seen[start] = true;
    while (!stack.empty()) {
        int u = stack.back();                      // look at the top frame, do not pop it yet
        if (nxt[u] < (int)adj[u].size()) {
            int v = adj[u][nxt[u]++];              // remember where to resume, like a paused call
            if (!seen[v]) { seen[v] = true; stack.push_back(v); }
        } else {
            stack.pop_back();                      // all neighbours done: u finishes ("return")
            post.push_back(u);
        }
    }
    return post;
}
int main() {
    vector<vector<int>> adj = {{1, 2}, {3, 4}, {4}, {}, {5}, {}};
    vector<bool> seen(6, false);
    vector<int> rec;
    recursive(0, adj, seen, rec);
    cout << "edges: 0->1 0->2 1->3 1->4 2->4 4->5\n";
    cout << "recursive post-order:";
    for (int x : rec) cout << " " << x;
    cout << "\niterative post-order:";
    for (int x : iterative(0, adj)) cout << " " << x;
    cout << "\n";
    int N = 200000;                                // a chain this deep would overflow a recursive DFS
    vector<vector<int>> chain(N);
    for (int i = 0; i + 1 < N; i++) chain[i].push_back(i + 1);
    vector<int> p = iterative(0, chain);
    cout << "chain of " << N << " nodes: visited " << p.size() << ", first finished " << p[0] << ", last finished " << p.back() << "\n";
    // Time O(V + E), space O(V) on the heap instead of the call stack
    return 0;
}

