using System;
using System.Collections.Generic;

class Program {
    static void Recursive(int u, int[][] adj, bool[] seen, List<int> post) {
        seen[u] = true;
        foreach (int v in adj[u]) if (!seen[v]) Recursive(v, adj, seen, post);
        post.Add(u);
    }
    static List<int> Iterative(int start, int[][] adj) {
        int n = adj.Length;
        bool[] seen = new bool[n];
        int[] nxt = new int[n];                    // nxt[u] = which neighbour of u to try next
        List<int> post = new List<int>();
        Stack<int> stack = new Stack<int>();
        stack.Push(start);
        seen[start] = true;
        while (stack.Count > 0) {
            int u = stack.Peek();                  // look at the top frame, do not pop it yet
            if (nxt[u] < adj[u].Length) {
                int v = adj[u][nxt[u]++];          // remember where to resume, like a paused call
                if (!seen[v]) { seen[v] = true; stack.Push(v); }
            } else {
                stack.Pop();                       // all neighbours done: u finishes ("return")
                post.Add(u);
            }
        }
        return post;
    }
    static void Main() {
        int[][] adj = { new[] {1, 2}, new[] {3, 4}, new[] {4}, new int[0], new[] {5}, new int[0] };
        List<int> rec = new List<int>();
        Recursive(0, adj, new bool[6], rec);
        string a = "recursive post-order:", b = "iterative post-order:";
        foreach (int x in rec) a += " " + x;
        foreach (int x in Iterative(0, adj)) b += " " + x;
        Console.WriteLine("edges: 0->1 0->2 1->3 1->4 2->4 4->5");
        Console.WriteLine(a);
        Console.WriteLine(b);
        int N = 200000;                            // a chain this deep would overflow a recursive DFS
        int[][] chain = new int[N][];
        for (int i = 0; i < N; i++) chain[i] = i + 1 < N ? new[] {i + 1} : new int[0];
        List<int> p = Iterative(0, chain);
        Console.WriteLine("chain of " + N + " nodes: visited " + p.Count + ", first finished " + p[0] + ", last finished " + p[p.Count - 1]);
        // Time O(V + E), space O(V) on the heap instead of the call stack
    }
}

