function ladder(begin, end, words) {
  const left = new Set(words);             // words not visited yet
  if (!left.has(end)) return 0;
  let level = [begin];
  let steps = 1;                           // the ladder length counts words, so begin is 1
  const letters = "abcdefghijklmnopqrstuvwxyz";
  while (level.length > 0) {
    const next = [];
    for (const w of level) {
      if (w === end) return steps;
      for (let i = 0; i < w.length; i++) { // change one position to each other letter
        for (const ch of letters) {
          if (ch === w[i]) continue;
          const cand = w.slice(0, i) + ch + w.slice(i + 1);
          if (left.has(cand)) {            // a real word we have not used: it is a neighbour
            left.delete(cand);             // removing it marks it visited
            next.push(cand);
          }
        }
      }
    }
    level = next;
    steps++;
  }
  return 0;
}
for (const words of [["hot", "dot", "dog", "lot", "log", "cog"], ["hot", "dot", "dog", "lot", "log"]]) {
  let line = "words:";
  for (const w of words) line += " " + w;
  console.log(line);
  const r = ladder("hit", "cog", words);
  console.log("  hit -> cog: " + (r ? r + " words in the shortest ladder" : "no ladder"));
}
// Time O(N * L * 26 * L) for N words of length L, space O(N * L)

