import java.util.*;

public class Main {
    static int ladder(String begin, String end, String[] words) {
        Set<String> left = new HashSet<>(Arrays.asList(words));   // words not visited yet
        if (!left.contains(end)) return 0;
        ArrayDeque<String> q = new ArrayDeque<>();
        q.add(begin);
        int steps = 1;                             // the ladder length counts words, so begin is 1
        while (!q.isEmpty()) {
            for (int k = q.size(); k > 0; k--) {
                String w = q.poll();
                if (w.equals(end)) return steps;
                char[] cs = w.toCharArray();
                for (int i = 0; i < cs.length; i++) {   // change one position to each other letter
                    char old = cs[i];
                    for (char ch = 'a'; ch <= 'z'; ch++) {
                        if (ch == old) continue;
                        cs[i] = ch;
                        String cand = new String(cs);
                        if (left.remove(cand)) q.add(cand);  // a real unused word: visit it once
                    }
                    cs[i] = old;                   // put the letter back before the next position
                }
            }
            steps++;
        }
        return 0;
    }
    public static void main(String[] args) {
        String[][] lists = {{"hot", "dot", "dog", "lot", "log", "cog"}, {"hot", "dot", "dog", "lot", "log"}};
        for (String[] words : lists) {
            System.out.println("words: " + String.join(" ", words));
            int r = ladder("hit", "cog", words);
            System.out.println("  hit -> cog: " + (r > 0 ? r + " words in the shortest ladder" : "no ladder"));
        }
        // Time O(N * L * 26 * L) for N words of length L, space O(N * L)
    }
}

