#include <bits/stdc++.h>
using namespace std;

int ladder(const string& begin, const string& end, const vector<string>& words) {
    unordered_set<string> left(words.begin(), words.end());   // words not visited yet
    if (!left.count(end)) return 0;
    queue<string> q;
    q.push(begin);
    int steps = 1;                                 // the ladder length counts words, so begin is 1
    while (!q.empty()) {
        for (int k = q.size(); k > 0; k--) {
            string w = q.front(); q.pop();
            if (w == end) return steps;
            for (size_t i = 0; i < w.size(); i++) {   // change one position to each other letter
                char old = w[i];
                for (char ch = 'a'; ch <= 'z'; ch++) {
                    if (ch == old) continue;
                    w[i] = ch;
                    if (left.erase(w)) q.push(w);  // a real unused word: visit it once
                }
                w[i] = old;                        // put the letter back before the next position
            }
        }
        steps++;
    }
    return 0;
}
int main() {
    vector<vector<string>> lists = {{"hot", "dot", "dog", "lot", "log", "cog"}, {"hot", "dot", "dog", "lot", "log"}};
    for (auto& words : lists) {
        cout << "words:";
        for (auto& w : words) cout << " " << w;
        cout << "\n";
        int r = ladder("hit", "cog", words);
        if (r > 0) cout << "  hit -> cog: " << r << " words in the shortest ladder\n";
        else cout << "  hit -> cog: no ladder\n";
    }
    // Time O(N * L * 26 * L) for N words of length L, space O(N * L)
    return 0;
}

