using System;
using System.Collections.Generic;

class Program {
    static int Ladder(string begin, string end, string[] words) {
        HashSet<string> left = new HashSet<string>(words);   // words not visited yet
        if (!left.Contains(end)) return 0;
        Queue<string> q = new Queue<string>();
        q.Enqueue(begin);
        int steps = 1;                             // the ladder length counts words, so begin is 1
        while (q.Count > 0) {
            for (int k = q.Count; k > 0; k--) {
                string w = q.Dequeue();
                if (w == end) return steps;
                char[] cs = w.ToCharArray();
                for (int i = 0; i < cs.Length; i++) {   // change one position to each other letter
                    char old = cs[i];
                    for (char ch = 'a'; ch <= 'z'; ch++) {
                        if (ch == old) continue;
                        cs[i] = ch;
                        string cand = new string(cs);
                        if (left.Remove(cand)) q.Enqueue(cand);  // a real unused word: visit it once
                    }
                    cs[i] = old;                   // put the letter back before the next position
                }
            }
            steps++;
        }
        return 0;
    }
    static void Main() {
        string[][] lists = { new[] {"hot", "dot", "dog", "lot", "log", "cog"}, new[] {"hot", "dot", "dog", "lot", "log"} };
        foreach (string[] words in lists) {
            Console.WriteLine("words: " + string.Join(" ", words));
            int r = Ladder("hit", "cog", words);
            Console.WriteLine("  hit -> cog: " + (r > 0 ? r + " words in the shortest ladder" : "no ladder"));
        }
        // Time O(N * L * 26 * L) for N words of length L, space O(N * L)
    }
}

