function findOrder(n, pairs) {
  const adj = Array.from({ length: n }, () => []);
  const indeg = new Array(n).fill(0);
  for (const [course, pre] of pairs) {
    adj[pre].push(course);                 // edge goes prerequisite -> course
    indeg[course]++;
  }
  const q = [];
  for (let c = 0; c < n; c++) if (indeg[c] === 0) q.push(c);  // includes isolated courses
  const order = [];
  let head = 0;
  while (head < q.length) {
    const u = q[head++];
    order.push(u);
    for (const v of adj[u]) {
      indeg[v]--;                          // one prerequisite of v is now done
      if (indeg[v] === 0) q.push(v);
    }
  }
  return order;                            // fewer than n courses means a cycle
}
function show(n, pairs) {
  let line = n + " courses, pairs [course,prerequisite]:";
  for (const [a, b] of pairs) line += " [" + a + "," + b + "]";
  console.log(line);
  const order = findOrder(n, pairs);
  if (order.length < n) {                  // never return the partial order as if it were valid
    console.log("  impossible: only " + order.length + " of " + n + " courses can be taken (cycle)");
  } else {
    let out = "  order:";
    for (const c of order) out += " " + c;
    console.log(out);
  }
}
show(5, [[1, 0], [2, 0], [3, 1], [3, 2]]);
show(4, [[1, 0], [2, 1], [1, 2], [3, 0]]);
// Time O(V + E), space O(V + E), no recursion so 100000 courses are fine

