import java.util.*;

public class Main {
    static List<Integer> findOrder(int n, int[][] pairs) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        int[] indeg = new int[n];
        for (int[] p : pairs) {
            adj.get(p[1]).add(p[0]);               // edge goes prerequisite -> course
            indeg[p[0]]++;
        }
        ArrayDeque<Integer> q = new ArrayDeque<>();
        for (int c = 0; c < n; c++) if (indeg[c] == 0) q.add(c);  // includes isolated courses
        List<Integer> order = new ArrayList<>();
        while (!q.isEmpty()) {
            int u = q.poll();
            order.add(u);
            for (int v : adj.get(u))
                if (--indeg[v] == 0) q.add(v);     // one prerequisite of v is now done
        }
        return order;                              // fewer than n courses means a cycle
    }
    static void show(int n, int[][] pairs) {
        StringBuilder line = new StringBuilder(n + " courses, pairs [course,prerequisite]:");
        for (int[] p : pairs) line.append(" [").append(p[0]).append(",").append(p[1]).append("]");
        System.out.println(line);
        List<Integer> order = findOrder(n, pairs);
        if (order.size() < n) {                    // never return the partial order as if it were valid
            System.out.println("  impossible: only " + order.size() + " of " + n + " courses can be taken (cycle)");
        } else {
            StringBuilder out = new StringBuilder("  order:");
            for (int c : order) out.append(" ").append(c);
            System.out.println(out);
        }
    }
    public static void main(String[] args) {
        show(5, new int[][]{{1, 0}, {2, 0}, {3, 1}, {3, 2}});
        show(4, new int[][]{{1, 0}, {2, 1}, {1, 2}, {3, 0}});
