console.log(line);
let level = [];
for (let u = 0; u < n; u++) if (indeg[u] === 0) level.push(u);  // nothing left to wait for
let stage = 0, built = 0;
while (level.length > 0) {
  stage++;
  // everything in one level is independent, so a build tool runs it in parallel
  let out = "stage " + stage + ":";
  for (const u of level) out += " " + names[u];
  console.log(out);
  built += level.length;
  const next = [];
  for (const u of level)
    for (const v of adj[u]) {
      indeg[v]--;                          // u is built: v waits for one target fewer
      if (indeg[v] === 0) next.push(v);
    }
  level = next;
}
// if built < n the leftover targets form a circular dependency
console.log("built " + built + " of " + n + " targets in " + stage + " stages");
