  for (let i = 0; i < n; i++) parent.push(i);
  for (const [a, b] of unions) {
    if (buggy) parent[a] = b;              // BUG: a may already hang under another root
    else parent[find(parent, a)] = find(parent, b);   // correct: link root to root
  }
  return parent;
}
function report(label, parent, x, y) {
  const same = find(parent, x) === find(parent, y);
  let line = label + " parent =";
  for (const p of parent) line += " " + p;
  console.log(line + " -> " + x + " and " + y + " connected? " + (same ? "yes" : "no"));
}
