public class Main {
    static int find(int[] parent, int x) {
        while (parent[x] != x) x = parent[x];
        return x;
    }
    static int[] run(boolean buggy, int n, int[][] unions) {
        int[] parent = new int[n];
        for (int i = 0; i < n; i++) parent[i] = i;
        for (int[] u : unions) {
            if (buggy) parent[u[0]] = u[1];        // BUG: a may already hang under another root
            else parent[find(parent, u[0])] = find(parent, u[1]);   // correct: link root to root
        }
        return parent;
    }
    static void report(String label, int[] parent, int x, int y) {
        boolean same = find(parent, x) == find(parent, y);
        StringBuilder line = new StringBuilder(label + " parent =");
        for (int p : parent) line.append(" ").append(p);
        System.out.println(line + " -> " + x + " and " + y + " connected? " + (same ? "yes" : "no"));
    }
    public static void main(String[] args) {
        int n = 3;
        int[][] unions = {{0, 1}, {0, 2}};         // after both, 0, 1 and 2 should be one group
        StringBuilder head = new StringBuilder("unions:");
        for (int[] u : unions) head.append(" ").append(u[0]).append("-").append(u[1]);
        System.out.println(head);
        report("buggy   (parent[a] = b): ", run(true, n, unions), 1, 2);
        report("correct (link the roots):", run(false, n, unions), 1, 2);
        // The second union overwrote parent[0], so node 1 was cut off from the group.
        // A test that only unions fresh nodes would never catch this.
        // Time per operation here is O(tree height); space O(n)
    }
}

