#include <bits/stdc++.h>
using namespace std;

int findRoot(const vector<int>& parent, int x) {
    while (parent[x] != x) x = parent[x];
    return x;
}
vector<int> run(bool buggy, int n, const vector<pair<int, int>>& unions) {
    vector<int> parent(n);
    iota(parent.begin(), parent.end(), 0);
    for (auto [a, b] : unions) {
        if (buggy) parent[a] = b;                  // BUG: a may already hang under another root
        else { int ra = findRoot(parent, a), rb = findRoot(parent, b); parent[ra] = rb; }  // correct: link root to root
    }
    return parent;
}
void report(const string& label, const vector<int>& parent, int x, int y) {
    bool same = findRoot(parent, x) == findRoot(parent, y);
    cout << label << " parent =";
    for (int p : parent) cout << " " << p;
    cout << " -> " << x << " and " << y << " connected? " << (same ? "yes" : "no") << "\n";
}
int main() {
    int n = 3;
    vector<pair<int, int>> unions = {{0, 1}, {0, 2}};   // after both, 0, 1 and 2 should be one group
    cout << "unions:";
    for (auto [a, b] : unions) cout << " " << a << "-" << b;
    cout << "\n";
    report("buggy   (parent[a] = b): ", run(true, n, unions), 1, 2);
    report("correct (link the roots):", run(false, n, unions), 1, 2);
    // The second union overwrote parent[0], so node 1 was cut off from the group.
    // A test that only unions fresh nodes would never catch this.
    // Time per operation here is O(tree height); space O(n)
    return 0;
}

