using System;

class Program {
    static int Find(int[] parent, int x) {
        while (parent[x] != x) x = parent[x];
        return x;
    }
    static int[] Run(bool buggy, int n, int[][] unions) {
        int[] parent = new int[n];
        for (int i = 0; i < n; i++) parent[i] = i;
        foreach (int[] u in unions) {
            if (buggy) parent[u[0]] = u[1];        // BUG: a may already hang under another root
            else { int ra = Find(parent, u[0]), rb = Find(parent, u[1]); parent[ra] = rb; }  // correct: link root to root
        }
        return parent;
    }
    static void Report(string label, int[] parent, int x, int y) {
        bool same = Find(parent, x) == Find(parent, y);
        string line = label + " parent =";
        foreach (int p in parent) line += " " + p;
        Console.WriteLine(line + " -> " + x + " and " + y + " connected? " + (same ? "yes" : "no"));
    }
    static void Main() {
        int n = 3;
        int[][] unions = { new[] {0, 1}, new[] {0, 2} };   // after both, 0, 1 and 2 should be one group
        string head = "unions:";
        foreach (int[] u in unions) head += " " + u[0] + "-" + u[1];
        Console.WriteLine(head);
        Report("buggy   (parent[a] = b): ", Run(true, n, unions), 1, 2);
        Report("correct (link the roots):", Run(false, n, unions), 1, 2);
        // The second union overwrote parent[0], so node 1 was cut off from the group.
        // A test that only unions fresh nodes would never catch this.
        // Time per operation here is O(tree height); space O(n)
    }
}
